'use strict';
const CACHE='murim-v112-sect-balance';
const FILES=['./','index.html','credits.html','characters.html','art-samples.html','samples/ninja-blue.png','samples/samurai-blue.png','samples/puny-player.png','samples/superpowers-characters.png','samples/kenney-sheet.png','samples/sources.json','samples/LICENSE-CC0.txt','samples/LICENSE-NOTES.txt','style.css','profile.js','sound.js','world.js','bosses.js','enemies.js','sect.js','trajectories.js','combat.js','vendor/proton.min.js','vendor/Proton-LICENSE.txt','vendor/wuxia-ui-pack.js','vendor/wuxia-sprites.js','vendor/WuxiaUI-LICENSE.txt','vfx.js','siege.js','arsenal.js','feedback.js','merchant.js','arena.js','links.js','vendor/jianghu-fx.js','vendor/PixelFx-LICENSE.txt','vendor/latest-pixel-items.js','equipment.js','jianghu.js','assets/peddler.png','assets/medicine-gourd.png','game.js','camp.js','controls.js','app.js','manifest.webmanifest','icon.svg','icon-192.png','icon-512.png'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(async cache=>{for(const file of FILES){const request=new Request(new URL(file,self.registration.scope),{cache:'reload'}),response=await fetch(request);if(!response.ok||response.redirected||response.type==='opaque')throw new Error('Unable to cache game asset');await cache.put(request,response)}}));self.skipWaiting()});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('murim-')&&k!==CACHE).map(k=>caches.delete(k))))).then(()=>self.clients.claim())});
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||!url.href.startsWith(self.registration.scope))return;if(event.request.mode==='navigate'){event.respondWith(fetch(event.request).catch(()=>caches.match(new URL('./',self.registration.scope))));return}if(url.searchParams.has('v')&&url.searchParams.get('v')!=='112.0'){event.respondWith(fetch(event.request));return}if(FILES.some(path=>new URL(path,self.registration.scope).pathname===url.pathname))event.respondWith(caches.match(new URL(url.pathname,self.location.origin)).then(hit=>hit||fetch(event.request)))});
